  FuncDriver.GetFormat      = pDrv->GetFormat;

DrawProp->LcdLayer = 0;
  DrawProp->LcdDevice = 0;
  FuncDriver.GetXSize(0, &DrawProp->LcdXsize);
  FuncDriver.GetYSize(0, &DrawProp->LcdYsize);
  FuncDriver.GetFormat(0, &DrawProp->LcdPixelFormat);
