  uint32_t buffer_address;

/*
   *               ######## Setup reload data variables ########
   */

/* Check if data size > Max I2C data size */
  if (pTxFull->Size > LPBAM_I2C_MAX_DATA_SIZE)
  {
    /* Update reload data information */
