  {
    return LPBAM_ERROR;
  }

/* Insert transmit data node to SPI queue */
  if (HAL_DMAEx_List_InsertNode_Tail(pQueue, &pDescriptor->pNodes[node_idx]) != HAL_OK)
  {
    return LPBAM_ERROR;
  }

return LPBAM_OK;
}

