{
  return NET_REALLOC(p, size);
}

void *calloc(size_t num, size_t size)
{
  return NET_CALLOC(num, size);
}

void *malloc(size_t size)
{
  return NET_MALLOC(size);
}

void free(void *p)
{
  NET_FREE(p);
}
