#define NET_PP_HTONL(X)           \
  ((((X) & 0x000000ffUL) << 24) | \
   (((X) & 0x0000ff00UL) <<  8) | \
   (((X) & 0x00ff0000UL) >>  8) | \
   (((X) & 0xff000000UL) >> 24))

#define NET_MAKEU32_FROM_4BYTES(A, B, C, D) \
  (((uint32_t)((A) & 0xff) << 24) |         \
   ((uint32_t)((B) & 0xff) << 16) |         \
   ((uint32_t)((C) & 0xff) << 8)  |         \
   ((uint32_t)((D) & 0xff)))

#define NET_IPADDR4_INIT(u32val)            { (u32val) }
#define NET_IPADDR4_INIT_BYTES(a, b, c, d)  NET_IPADDR4_INIT(NET_PP_HTONL(NET_MAKEU32_FROM_4BYTES((a), (b), (c), (d))))

