typedef struct net_sockaddr
{
  uint8_t sa_len;
  uint8_t sa_family;
  char_t  sa_data[14];
} net_sockaddr_t;

/* IPV4 address, with 8 stuffing bytes. */
#define NET_SIN_ZERO_LEN    8
typedef struct net_sockaddr_in
{
  uint8_t       sin_len;
  uint8_t       sin_family;
  uint16_t      sin_port;
  net_in_addr_t sin_addr;
  char_t        sin_zero[NET_SIN_ZERO_LEN];
} net_sockaddr_in_t;

