int32_t returncode_lwip2net(int32_t ret_in)
{
  int32_t ret = ret_in;
  if (ret_in == -1)
  {
    if (errno == EWOULDBLOCK)
    {
      ret = 0;
    }
  }
  else if (ret_in == 0)
  {
    /* connection close */
    ret = NET_ERROR_DISCONNECTED;
  }
  else
  {
    /* Does not catch ret value otherwise. */
    ret = ret_in;
  }
  return ret;
}

