{
#ifdef MBEDTLS_THREADING_ALT
  mbedtls_threading_set_alt(mutex_init, mutex_free, (mutex_t) mutex_lock, (mutex_t)mutex_unlock);
#endif /* MBEDTLS_THREADING_ALT */
}

