static int32_t net_cypress_whd_if_disconnect(net_if_handle_t *pnetif)
{
  int32_t ret;
  ret = net_ip_disconnect(pnetif);
  if (ret == NET_OK)
  {
    ret = net_state_manage_event(pnetif, NET_EVENT_INTERFACE_READY);
  }
  return ret;
