                inB2 = arm_nn_read_q15x2_ia(&pB);

sum = __SMLAD(inA2, inB2, sum);

colCnt--;
            }
            colCnt = ch_im_in * dim_kernel * dim_kernel & 0x3;
            while (colCnt)
            {
                q7_t inA1 = *pA++;
