    {
        vecSrcA = vld1q(pSrcA);
        vecSrcB = vld1q(pSrcB);

vst1q(pDst, vandq_u16(vecSrcA, vecSrcB) );

pSrcA += 8;
        pSrcB += 8;
        pDst  += 8;

