#else
void arm_negate_q31(
  const q31_t * pSrc,
        q31_t * pDst,
        uint32_t blockSize)
{
        uint32_t blkCnt;                               /* Loop counter */
        q31_t in;                                      /* Temporary input variable */

#if defined (ARM_MATH_LOOPUNROLL)

/* Loop unrolling: Compute 4 outputs at a time */
  blkCnt = blockSize >> 2U;

while (blkCnt > 0U)
