#if defined(ARM_MATH_MVEI) && !defined(ARM_MATH_AUTOVECTORIZE)
    uint16x8_t vecSrc;

/* Compute 8 outputs at a time */
    blkCnt = blockSize >> 3;

while (blkCnt > 0U)
    {
        vecSrc = vld1q(pSrc);

vst1q(pDst, vmvnq_u16(vecSrc) );

pSrc += 8;
        pDst += 8;

/* Decrement the loop counter */
        blkCnt--;
    }

/* Tail */
    blkCnt = blockSize & 7;

