{

uint32_t blockSize = numSamples * CMPLX_DIM;   /* loop counters */
    uint32_t blkCnt;
    q31x4x2_t vecSrc;
    q31_t in;                                      /* Temporary input variable */
    q31x4_t zero;

zero = vdupq_n_s32(0);

/* Compute 4 real samples at a time */
    blkCnt = blockSize >> 3U;

while (blkCnt > 0U)
    {

vecSrc = vld2q(pSrc);
        vecSrc.val[1] = vqsubq(zero, vecSrc.val[1]);
        vst2q(pDst,vecSrc);
