float16_t arm_braycurtis_distance_f16(const float16_t *pA,const float16_t *pB, uint32_t blockSize)
{
   _Float16 accumDiff=0.0f16, accumSum=0.0f16, tmpA, tmpB;

while(blockSize > 0)
   {
      tmpA = *pA++;
      tmpB = *pB++;
