/* 0.5 in q11 */
   uint32_t inc  = LOQ_Q31_Q32_HALF >> (LOG_Q31_INTEGER_PART + 1);

/* Will compute y = log2(x) for 1 <= x < 2.0 */
   uint32x4_t x;

/* q11 */
   uint32x4_t y = vdupq_n_u32(0);

