        uint32_t blockSize)
{
  uint32_t  blkCnt;           /* loop counters */

#if defined(ARM_MATH_MVEI) && !defined(ARM_MATH_AUTOVECTORIZE)

q31x4_t src;
  q31x4_t dst;

blkCnt = blockSize >> 2;

while (blkCnt > 0U)
  {
      src = vld1q(pSrc);
      dst = vlogq_q31(src);
      vst1q(pDst, dst);

pSrc += 4;
      pDst += 4;
      /* Decrement loop counter */
      blkCnt--;
  }

blkCnt = blockSize & 3;
  #else
  blkCnt = blockSize;
  #endif

while (blkCnt > 0U)
  {
     *pDst++=arm_scalar_log_q31(*pSrc++);

blkCnt--;
  }

}

