acc0 = asrl(acc0, 31 - 8);
                acc1 = asrl(acc1, 31 - 8);
                acc2 = asrl(acc2, 31 - 8);
                acc3 = asrl(acc3, 31 - 8);

*pDst++ = (q31_t) acc0;
                *pDst++ = (q31_t) acc1;
                *pDst++ = (q31_t) acc2;
