       {
         return(ARM_MATH_DECOMPOSITION_FAILURE);
       }

invSqrtVj = 1.0f/sqrtf(pG[i * n + i]);
       for(j=i; j < n ; j++)
       {
         pG[j * n + i] = pG[j * n + i] * invSqrtVj ;
       }
    }

status = ARM_MATH_SUCCESS;

}

/* Return to application */
  return (status);
}

