    acc3 = vmlaldavxq_s32(vecA, vecB);

vecA = vldrwq_z_s32(&pInA0[4], p0);
    acc0 = vmlsldavaq_s32(acc0, vecA, vecB1);
    acc1 = vmlaldavaxq_s32(acc1, vecA, vecB1);

vecA = vldrwq_z_s32(&pInA1[4], p0);
