                        blkCnt = numCols & 7;
                        if (blkCnt > 0U)
                        {
                            mve_pred16_t p0 = vctp16q(blkCnt);

vecA = vldrhq_f16(pTmpA);
                            vecB = vldrhq_f16(pTmpB);
                            vstrhq_p_f16(pTmpB, vecA, p0);
                            vstrhq_p_f16(pTmpA, vecB, p0);
