        pIn1 = pInA;

#if defined (ARM_MATH_LOOPUNROLL)

/* Loop unrolling: Compute 4 MACs at a time. */
        colCnt = numColsA >> 2U;

/* matrix multiplication */
        while (colCnt > 0U)
