     * compute 2 rows in parrallel
     */
    if (row >= 2)
    {
        float16_t const    *pSrcA0Vec, *pSrcA1Vec, *pInVec;
        f16x8_t            vecIn, acc0, acc1;
        float16_t const     *pSrcVecPtr = pSrcVec;

