blkCnt = numCols >> 3;
        while (blkCnt > 0U)
        {
            f16x8_t vecA;

vecIn = vld1q(pInVec);      
            pInVec += 8;
            vecA = vld1q(pSrcA0Vec);    
            pSrcA0Vec += 8;
            acc0 = vfmaq(acc0, vecIn, vecA);

blkCnt--;
