fValue = *pInput++ - fMean;
    fSum += fValue * fValue;

fValue = *pInput++ - fMean;
    fSum += fValue * fValue;

fValue = *pInput++ - fMean;
    fSum += fValue * fValue;

/* Decrement loop counter */
    blkCnt--;
