  blkCnt = blockSize;

while (blkCnt > 0U)
  {
    /* C = (A[0] + A[1] + A[2] + ... + A[blockSize-1]) */

sum += *pInput++;

/* Decrement loop counter */
    blkCnt--;
  }

/* C = (A[0] + A[1] + A[2] + ... + A[blockSize-1]) / blockSize  */
  fMean = sum / (float64_t) blockSize;

pInput = pSrc;

/* Initialize blkCnt with number of samples */
  blkCnt = blockSize;

while (blkCnt > 0U)
  {
    fValue = *pInput++ - fMean;
    fSum += fValue * fValue;

/* Decrement loop counter */
    blkCnt--;
  }

