void arm_fill_q15(
  q15_t value,
  q15_t * pDst,
  uint32_t blockSize)
{
  uint32_t blkCnt;  
  blkCnt = blockSize >> 3;
  while (blkCnt > 0U)
  {

vstrhq_s16(pDst,vdupq_n_s16(value));
        /*
         * Decrement the blockSize loop counter
         * Advance vector source and destination pointers
         */
        pDst += 8;
        blkCnt --;
    }

blkCnt = blockSize & 7;
  while (blkCnt > 0U)
  {
    /* C = value */

/* Fill value in destination buffer */
    *pDst++ = value;

/* Decrement loop counter */
    blkCnt--;
