   n2 = fftLen;
   n1 = n2;

/* n2 = fftLen/4 */
   n2 >>= 2U;
   i0 = 0U;
   ia1 = 0U;

j = n2;

/*  Calculation of first stage */
   do
   {
      /*  index calculation for the input as, */
      /*  pSrc[i0 + 0], pSrc[i0 + fftLen/4], pSrc[i0 + fftLen/2], pSrc[i0 + 3fftLen/4] */
      i1 = i0 + n2;
      i2 = i1 + n2;
      i3 = i2 + n2;

xaIn = pSrc[(2U * i0)];
      yaIn = pSrc[(2U * i0) + 1U];

xbIn = pSrc[(2U * i1)];
      ybIn = pSrc[(2U * i1) + 1U];

xcIn = pSrc[(2U * i2)];
      ycIn = pSrc[(2U * i2) + 1U];

xdIn = pSrc[(2U * i3)];
      ydIn = pSrc[(2U * i3) + 1U];

/* xa + xc */
      Xaplusc = xaIn + xcIn;
      /* xb + xd */
      Xbplusd = xbIn + xdIn;
      /* ya + yc */
      Yaplusc = yaIn + ycIn;
      /* yb + yd */
      Ybplusd = ybIn + ydIn;

