      i1 = i0 + n2;
      i2 = i1 + n2;
      i3 = i2 + n2;

/*  Butterfly implementation */
      xaIn = pSrc[(2U * i0)];
      yaIn = pSrc[(2U * i0) + 1U];

xcIn = pSrc[(2U * i2)];
      ycIn = pSrc[(2U * i2) + 1U];

xbIn = pSrc[(2U * i1)];
      ybIn = pSrc[(2U * i1) + 1U];

xdIn = pSrc[(2U * i3)];
