    {
      arm_dot_prod_q31(pSrc+S->filterPos[i],
        &(S->filterCoefs[coefsPos]),
        S->filterLengths[i],
        &result);

coefsPos += S->filterLengths[i];

// q16.48 - fftShift
      result += MICRO_Q31;
      result >>= (SHIFT_MELFILTER_SATURATION_Q31 + 18);
      // q16.29 - fftShift - satShift
      pTmp[i] = __SSAT(result,31) ;

