twR = *pCoeff++;
      twI = *pCoeff++;

t1a = xAR - xBR ;
      t1b = xAI + xBI ;

r = twR * t1a;
      s = twI * t1b;
      t = twI * t1a;
      u = twR * t1b;

// real(tw * (xA - xB)) = twR * (xAR - xBR) - twI * (xAI - xBI);
      // imag(tw * (xA - xB)) = twI * (xAR - xBR) + twR * (xAI - xBI);
      *pOut++ = 0.5 * (xAR + xBR - r - s ); //xAR
      *pOut++ = 0.5 * (xAI - xBI + t - u ); //xAI

pA += 2;
      pB -= 2;
      k--;
   }

}

