 * @param[in]  num_adds 	number of additions
 * @return guard bits
 * The function Caluclates the number of guard bits
 * depending on the numtaps
 */

uint32_t arm_calc_guard_bits (uint32_t num_adds)
{
  uint32_t i = 1, j = 0;

if (num_adds == 1)
    {
      return (0);
    }

while (i < num_adds)
    {
      i = i * 2;
      j++;
    }

return (j);
}

