  }
  else
  {
    config &= (uint16_t) ~VEML6030_CONF_GAIN_1_4;
    config |= (uint16_t)Gain;
    ret = VEML6030_OK;
    if (veml6030_write_reg(&pObj->Ctx, VEML6030_REG_ALS_CONF, &config, 2) != 0)
